(3065709, 429892, 16488, '<td valign="top">This has an unappealing pink cast to it. Not sure why the subject should hold my interest.</td>', 'This has an unappealing pink cast to it. Not sure why the subject should hold my interest.', '2006-11-27 11:47:10.000000', NULL, 1),
(3065712, 432010, 16488, '<td valign="top">I don''t think the shadow enhances the form of the bottle. Would like to see the entire bottle...the way it is the artwork on the bottle has become the subject which is not very interesting in this presentation.</td>', 'I don''t think the shadow enhances the form of the bottle. Would like to see the entire bottle...the way it is the artwork on the bottle has become the subject which is not very interesting in this presentation.', '2006-11-27 11:49:02.000000', NULL, 1),
