(3065870, 431610, 30049, '<td valign="top">Very well done high-key photo.  The blowouts on the lower cheek and nose spoil it just a tad for me.  Great detail in the eyes.  Good luck in the challenge.</td>', 'Very well done high-key photo.  The blowouts on the lower cheek and nose spoil it just a tad for me.  Great detail in the eyes.  Good luck in the challenge.', '2006-11-27 13:00:28.000000', NULL, 1),
(3065871, 431463, 67388, '<td valign="top">this would be great stationery stock<br/>7</td>', 'this would be great stationery stock7', '2006-11-27 13:01:11.000000', NULL, 1),
(3065873, 430897, 30049, '<td valign="top">Great details in the subject.  Works well with the high-key look, and you''ve handled the lighting quite nicely.  Good luck in the challenge.</td>', 'Great details in the subject.  Works well with the high-key look, and you''ve handled the lighting quite nicely.  Good luck in the challenge.', '2006-11-27 13:01:46.000000', NULL, 1),
(3065876, 431967, 16488, '<td valign="top">Wish the logo wasn''t showing at all...I think it''d be more interesting as a study in form.</td>', 'Wish the logo wasn''t showing at all...I think it''d be more interesting as a study in form.', '2006-11-27 13:03:24.000000', NULL, 1),
(3065877, 431524, 30049, '<td valign="top">He-he.  Cute.  This would go over a little better I think if the background was a truer white.  Has a blue cast to it currently (which easily happens with poster board or other white background materials inside).  Using custom white balance on your camera can help some also.  Anyway, good luck in the challenge.</td>', 'He-he.  Cute.  This would go over a little better I think if the background was a truer white.  Has a blue cast to it currently (which easily happens with poster board or other white background materials inside).  Using custom white balance on your camera can help some also.  Anyway, good luck in the challenge.', '2006-11-27 13:03:48.000000', NULL, 1),
(3065889, 432002, 67152, '<td valign="top">i like the contrast and the angle of this shot.</td>', 'i like the contrast and the angle of this shot.', '2006-11-27 13:10:30.000000', NULL, 1),
(3065890, 432010, 67152, '<td valign="top">I don''t like the shadow on the left side of the image - the outline of the bottle (seen on the right) is much more appealing.</td>', 'I don''t like the shadow on the left side of the image - the outline of the bottle (seen on the right) is much more appealing.', '2006-11-27 13:11:06.000000', NULL, 1),
