(3066759, 430445, 66597, '<td valign="top">The orchids are lovely. I don''t like the grey tone of the background so much.</td>', 'The orchids are lovely. I don''t like the grey tone of the background so much.', '2006-11-27 19:28:06.000000', NULL, 1),
(3066768, 432056, 66597, '<td valign="top">I wish there was just a bit more distinction between subject and background, and the placement of shadows at top of flower look a bit unnatural. The flower itself and stamens are lovely and well composed.</td>', 'I wish there was just a bit more distinction between subject and background, and the placement of shadows at top of flower look a bit unnatural. The flower itself and stamens are lovely and well composed.', '2006-11-27 19:29:33.000000', NULL, 1),
(3066771, 431947, 66597, '<td valign="top">I like the expression on the llama''s face. However, I think the whites show very grey in this photo. You might consider shooting the llama without the tree, as there is a lot "going on" in this photo and subject gets a bit lost.</td>', 'I like the expression on the llama''s face. However, I think the whites show very grey in this photo. You might consider shooting the llama without the tree, as there is a lot "going on" in this photo and subject gets a bit lost.', '2006-11-27 19:30:47.000000', NULL, 1),
(3066773, 431598, 66597, '<td valign="top">I like the concept, but I wish there was just a bit more definition in the lines of the subject.</td>', 'I like the concept, but I wish there was just a bit more definition in the lines of the subject.', '2006-11-27 19:31:40.000000', NULL, 1),
(3066776, 431704, 66597, '<td valign="top">I love the subject and colors in this photo. The composition does not have quite enough breathing room perhaps, due to a very close crop.</td>', 'I love the subject and colors in this photo. The composition does not have quite enough breathing room perhaps, due to a very close crop.', '2006-11-27 19:32:30.000000', NULL, 1),
(3066780, 432051, 66597, '<td valign="top">My first thought is that is looks like the daisy has horns, not necessarily a bad thing, but not necessarily what you were going for. I''m not sure I like the mixture of hard / soft and desat.</td>', 'My first thought is that is looks like the daisy has horns, not necessarily a bad thing, but not necessarily what you were going for. I''m not sure I like the mixture of hard / soft and desat.', '2006-11-27 19:33:43.000000', NULL, 1),
(3066785, 432024, 66597, '<td valign="top">I very much like the textures and softness in this photo. I''m actually a bit distracted by the title (though I would not vote down based on that), as I''m not sure how synethesia fits into this. Great use of makeup on eyes. 8.</td>', 'I very much like the textures and softness in this photo. I''m actually a bit distracted by the title (though I would not vote down based on that), as I''m not sure how synethesia fits into this. Great use of makeup on eyes. 8.', '2006-11-27 19:35:44.000000', NULL, 1),
(3066791, 431950, 66597, '<td valign="top">The yellow cast to the whites might need a bit of tempering.</td>', 'The yellow cast to the whites might need a bit of tempering.', '2006-11-27 19:38:23.000000', NULL, 1),
(3066796, 432076, 14211, '<td valign="top">I like the creativity.</td>', 'I like the creativity.', '2006-11-27 19:39:01.000000', NULL, 1),
(3066797, 432010, 66597, '<td valign="top">I really like the concept. Maybe onsider a layer mask or background toning to decrease the bluish cast.</td>', 'I really like the concept. Maybe onsider a layer mask or background toning to decrease the bluish cast.', '2006-11-27 19:39:38.000000', NULL, 1),
(3066798, 429892, 66597, '<td valign="top">The concept is funny. The focus is not as sharp as it might be, though, and the pinkish-gray cast makes the cotton balls look a little dirty.</td>', 'The concept is funny. The focus is not as sharp as it might be, though, and the pinkish-gray cast makes the cotton balls look a little dirty.', '2006-11-27 19:40:21.000000', NULL, 1);
