(3066820, 431816, 66597, '<td valign="top">Creative departure from many flowers/seashells/feathers, etc. Great lighting and sharp focus.</td>', 'Creative departure from many flowers/seashells/feathers, etc. Great lighting and sharp focus.', '2006-11-27 19:44:32.000000', NULL, 1),
(3066821, 432086, 327, '<td valign="top">Second baby girl in two days that I''ve seen named Ava. Love it, she is precious.</td>', 'Second baby girl in two days that I''ve seen named Ava. Love it, she is precious.', '2006-11-27 19:44:44.000000', NULL, 1),
