(3068672, 430896, 54838, '<td valign="top">NICE!  Not sure I get the whole "Light on White" idea here, but there is at least a white theme.  Great portrait!</td>', 'NICE!  Not sure I get the whole "Light on White" idea here, but there is at least a white theme.  Great portrait!', '2006-11-28 16:21:33.000000', NULL, 1),
(3068696, 431405, 22748, '<td valign="top">Awesome! Very creative, it is masterfully done. I don''t know how it''s done, but it is great. The composition is simple, with no distracting elements, but the impact is huge.</td>', 'Awesome! Very creative, it is masterfully done. I don''t know how it''s done, but it is great. The composition is simple, with no distracting elements, but the impact is huge.', '2006-11-28 16:32:28.000000', NULL, 1),
(3068700, 431636, 16488, '<td valign="top">I like everything about this except for the instrusive bits of what seems to be a second child.</td>', 'I like everything about this except for the instrusive bits of what seems to be a second child.', '2006-11-28 16:33:31.000000', NULL, 1),
(3068701, 431822, 16488, '<td valign="top">Strong composition. I love the play of light on the petals...it really sculpts them! Nicely done!</td>', 'Strong composition. I love the play of light on the petals...it really sculpts them! Nicely done!', '2006-11-28 16:34:38.000000', NULL, 1),
(3068703, 431524, 22748, '<td valign="top">Interesting... how did you make the light glow? This image made me pause to consider it. I don''t like the flat light and harsh shadows created by what appears to be on-camera flash, however. I think that if this were naturally lit it would be awesome.</td>', 'Interesting... how did you make the light glow? This image made me pause to consider it. I don''t like the flat light and harsh shadows created by what appears to be on-camera flash, however. I think that if this were naturally lit it would be awesome.', '2006-11-28 16:35:09.000000', NULL, 1),
(3068705, 431411, 16488, '<td valign="top">Pretty tones here. I think the softness is a bit over the top, though, and the pose (rotated 90 degrees?) seems oddly unnatural.</td>', 'Pretty tones here. I think the softness is a bit over the top, though, and the pose (rotated 90 degrees?) seems oddly unnatural.', '2006-11-28 16:35:32.000000', NULL, 1);
