(3069316, 431756, 66384, '<td valign="top">To me, words like ''charming'', ''lovely'', ''wonderful'', etc. in the titles are just attempts to influence the vote.  I resent that, and usually deduct a point.</td>', 'To me, words like ''charming'', ''lovely'', ''wonderful'', etc. in the titles are just attempts to influence the vote.  I resent that, and usually deduct a point.', '2006-11-28 21:36:43.000000', NULL, 1),
(3069324, 431804, 66384, '<td valign="top">I like this a lot, and I''d like to know how you did it.</td>', 'I like this a lot, and I''d like to know how you did it.', '2006-11-28 21:39:41.000000', NULL, 1),
(3069342, 431976, 66384, '<td valign="top">Lovely simplicity</td>', 'Lovely simplicity', '2006-11-28 21:48:50.000000', NULL, 1),
