(3069468, 432084, 32872, '<td valign="top">Wow, wow, wow.....this is the cutest, sweetest image I''ve ever seen of a baby.</td>', 'Wow, wow, wow.....this is the cutest, sweetest image I''ve ever seen of a baby.', '2006-11-28 22:27:53.000000', NULL, 1),
(3069470, 431880, 30049, '<td valign="top">Right concept with a nice subject.  Somehow, not much seems in focus.  Maybe because it''s all muted a bit (sorry, not sure how else to describe it).  Could be the condensation on the glass and glare from the lighting around the top (area without condensation)?  The background seems more yellow than white (really evident from the thumbnail view).  I like the composition with the off-centering and upper-right placement of the glass.  Good luck in the challenge.</td>', 'Right concept with a nice subject.  Somehow, not much seems in focus.  Maybe because it''s all muted a bit (sorry, not sure how else to describe it).  Could be the condensation on the glass and glare from the lighting around the top (area without condensation)?  The background seems more yellow than white (really evident from the thumbnail view).  I like the composition with the off-centering and upper-right placement of the glass.  Good luck in the challenge.', '2006-11-28 22:28:23.000000', NULL, 1),
(3069481, 431402, 64795, '<td valign="top">This is really cute!  I love her expression!</td>', 'This is really cute!  I love her expression!', '2006-11-28 22:30:03.000000', NULL, 1),
