INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3073553, 431880, 23484, '<td valign="top">This is a really nice shot but I would like to see a tad more of the glass. 7</td>', 'This is a really nice shot but I would like to see a tad more of the glass. 7', '2006-11-29 19:59:33.000000', NULL, 1),
(3073845, 431061, 3306, '<td valign="top">This is a really interesting and creative idea but the sharpness and focus is a little bit off.</td>', 'This is a really interesting and creative idea but the sharpness and focus is a little bit off.', '2006-11-29 21:33:50.000000', NULL, 1),
(3073930, 431405, 64795, '<td valign="top">I really like this picture, but the nails are a little distracting.</td>', 'I really like this picture, but the nails are a little distracting.', '2006-11-29 22:07:21.000000', NULL, 1),
(3073940, 432076, 64795, '<td valign="top">Hehehe!  Yay for woody!</td>', 'Hehehe!  Yay for woody!', '2006-11-29 22:09:36.000000', NULL, 1),
(3073945, 432093, 64795, '<td valign="top">The stopped motion is perfect!  Flawless!</td>', 'The stopped motion is perfect!  Flawless!', '2006-11-29 22:11:09.000000', NULL, 1),
(3073957, 431659, 64795, '<td valign="top">hehe!</td>', 'hehe!', '2006-11-29 22:14:04.000000', NULL, 1),
(3074305, 431640, 45475, '<td valign="top">A beautiful woman, there''s no doubt. I love the effect the post work plays on her face and hair. Wonderfully soft but crisp at the same time. Great job on that. The issue that lets this image down though, as I see it, is the severity of the clipping around her right breast. It appears as though suspended in mid air as the texture and form of her torso has completely disappeared. I can''t seem to get past that once my attention is drawn to it. :(</td>', 'A beautiful woman, there''s no doubt. I love the effect the post work plays on her face and hair. Wonderfully soft but crisp at the same time. Great job on that. The issue that lets this image down though, as I see it, is the severity of the clipping around her right breast. It appears as though suspended in mid air as the texture and form of her torso has completely disappeared. I can''t seem to get past that once my attention is drawn to it. :(', '2006-11-29 23:58:15.000000', NULL, 1),
(3074319, 432024, 2389, '<td valign="top">Makes me want to get my membership up-to-date just so I can give you a 10!</td>', 'Makes me want to get my membership up-to-date just so I can give you a 10!', '2006-11-30 00:02:34.000000', NULL, 1),
(3074324, 431402, 68482, '<td valign="top">Wow!  Beautiful...You''re right, it makes me happy!</td>', 'Wow!  Beautiful...You''re right, it makes me happy!', '2006-11-30 00:03:44.000000', NULL, 1),
(3074333, 431758, 42013, '<td valign="top">Looks like the BG could use a larger blast of white.</td>', 'Looks like the BG could use a larger blast of white.', '2006-11-30 00:05:47.000000', NULL, 1),
(3074340, 431945, 42013, '<td valign="top">Good exposure. I see a wierdly shaped diamond irregularity in the foreground left, about the same size as the ornament. Maybe just my monitor or a funny shadow remnant.</td>', 'Good exposure. I see a wierdly shaped diamond irregularity in the foreground left, about the same size as the ornament. Maybe just my monitor or a funny shadow remnant.', '2006-11-30 00:07:03.000000', NULL, 1),
