(3079286, 431874, 28532, '<td valign="top">Adorable - love the outfit!  Fun shot!!</td>', 'Adorable - love the outfit!  Fun shot!!', '2006-12-01 13:41:42.000000', NULL, 1),
(3079291, 431906, 28532, '<td valign="top">I love this! Adding to my favorites - nicely done!!</td>', 'I love this! Adding to my favorites - nicely done!!', '2006-12-01 13:44:13.000000', NULL, 1),
(3079295, 431156, 28532, '<td valign="top">oooo - nice! Excellent shot!</td>', 'oooo - nice! Excellent shot!', '2006-12-01 13:46:10.000000', NULL, 1),
(3079301, 431411, 28532, '<td valign="top">Beautiful - love the soft look - Excellent!!</td>', 'Beautiful - love the soft look - Excellent!!', '2006-12-01 13:48:13.000000', NULL, 1),
(3079305, 431705, 28532, '<td valign="top">Sweet - excellent shot!!</td>', 'Sweet - excellent shot!!', '2006-12-01 13:50:35.000000', NULL, 1),
(3079308, 431435, 28532, '<td valign="top">WOW - beautifully done!!  Adding to my favs - Nice Shot!!</td>', 'WOW - beautifully done!!  Adding to my favs - Nice Shot!!', '2006-12-01 13:51:17.000000', NULL, 1),
(3079315, 431266, 28532, '<td valign="top">Awesome shot - the eyes are fantastic!!  Excellent!!</td>', 'Awesome shot - the eyes are fantastic!!  Excellent!!', '2006-12-01 13:52:10.000000', NULL, 1),
(3079324, 431326, 28532, '<td valign="top">This is cool - I really like the composition - nicely done!!</td>', 'This is cool - I really like the composition - nicely done!!', '2006-12-01 13:54:19.000000', NULL, 1),
(3079342, 431051, 58610, '<td valign="top">Clever.</td>', 'Clever.', '2006-12-01 13:59:48.000000', NULL, 1),
(3079346, 431402, 28532, '<td valign="top">What a sweet shot and cute little smile!!  Looks like it was tones of fun - Excellent shot!!</td>', 'What a sweet shot and cute little smile!!  Looks like it was tones of fun - Excellent shot!!', '2006-12-01 14:01:07.000000', NULL, 1),
(3079349, 430159, 50982, '<td valign="top">Wonderfully creative. Focus could be sharper and deeper though to include all the letters.</td>', 'Wonderfully creative. Focus could be sharper and deeper though to include all the letters.', '2006-12-01 14:01:52.000000', NULL, 1),
(3079359, 431976, 58610, '<td valign="top">Very nice composition. I like the way the feather almost disappears into the background,but not quite. I''m also tempted to grab the pen and use the backdrop as paper to write on. Also, the beautiful reflection in the ink well adds depth (both physical and tonal) to an otherwise rather flat photo. Very simple and successful.</td>', 'Very nice composition. I like the way the feather almost disappears into the background,but not quite. I''m also tempted to grab the pen and use the backdrop as paper to write on. Also, the beautiful reflection in the ink well adds depth (both physical and tonal) to an otherwise rather flat photo. Very simple and successful.', '2006-12-01 14:07:49.000000', NULL, 1),
(3079367, 431203, 32345, '<td valign="top">I like the composition of this picture with the soft pastel colors. Well done.</td>', 'I like the composition of this picture with the soft pastel colors. Well done.', '2006-12-01 14:13:24.000000', NULL, 1),
(3079369, 431789, 32345, '<td valign="top">Very good composition, well done.</td>', 'Very good composition, well done.', '2006-12-01 14:13:33.000000', NULL, 1),
(3079376, 431012, 32345, '<td valign="top">Great action shot.</td>', 'Great action shot.', '2006-12-01 14:14:25.000000', NULL, 1),
(3079377, 432076, 58610, '<td valign="top">Great title and concept. I think you have too many shades of white in the background. Probably just lighting differences, but I find it distracts from the subject(s).</td>', 'Great title and concept. I think you have too many shades of white in the background. Probably just lighting differences, but I find it distracts from the subject(s).', '2006-12-01 14:14:40.000000', NULL, 1),
(3079379, 431087, 32345, '<td valign="top">Really nice horse portrait. Great details. It would have been a killer picture without the harness.</td>', 'Really nice horse portrait. Great details. It would have been a killer picture without the harness.', '2006-12-01 14:15:11.000000', NULL, 1),
(3079380, 431441, 32345, '<td valign="top">This is really sharp, well done.</td>', 'This is really sharp, well done.', '2006-12-01 14:15:13.000000', NULL, 1),
(3079383, 431756, 58610, '<td valign="top">Highlights on her face are just a tad too bright, but otherwise, yes, a charming photo.</td>', 'Highlights on her face are just a tad too bright, but otherwise, yes, a charming photo.', '2006-12-01 14:15:46.000000', NULL, 1),
(3079394, 430105, 58610, '<td valign="top">I think I''ll pass, thank you. (On the dishes, that is.(;l) Not quite in focus on the plate, and the composition lacks a strong subject. Cute idea.</td>', 'I think I''ll pass, thank you. (On the dishes, that is.(;l) Not quite in focus on the plate, and the composition lacks a strong subject. Cute idea.', '2006-12-01 14:20:07.000000', NULL, 1),
(3079469, 431405, 56534, '<td valign="top">creative.  i like the ephermeral quality</td>', 'creative.  i like the ephermeral quality', '2006-12-01 14:57:17.000000', NULL, 1),
(3079479, 430266, 56534, '<td valign="top">the value is beautifully done.  i think the curves on the lower right hand compliment the semi linearity of the petals</td>', 'the value is beautifully done.  i think the curves on the lower right hand compliment the semi linearity of the petals', '2006-12-01 15:03:18.000000', NULL, 1),
(3079481, 431433, 32345, '<td valign="top">Beautifull, the different color of the eyes is stunning. Good luck</td>', 'Beautifull, the different color of the eyes is stunning. Good luck', '2006-12-01 15:03:59.000000', NULL, 1),
(3079482, 431086, 32345, '<td valign="top">Very good composition with the open space at the bottom right, I like it. Well done</td>', 'Very good composition with the open space at the bottom right, I like it. Well done', '2006-12-01 15:04:03.000000', NULL, 1),
(3079484, 432008, 32345, '<td valign="top">Very nice picture, I love the point of vue. Well done.</td>', 'Very nice picture, I love the point of vue. Well done.', '2006-12-01 15:04:06.000000', NULL, 1),
(3079485, 431061, 56534, '<td valign="top">really beautiful, the image ie original.  the light contour of silver, breaking of 3rds rule.  wow.  beautiful</td>', 'really beautiful, the image ie original.  the light contour of silver, breaking of 3rds rule.  wow.  beautiful', '2006-12-01 15:04:06.000000', NULL, 1),
(3079488, 432041, 32345, '<td valign="top">Great concept, really nicely done.</td>', 'Great concept, really nicely done.', '2006-12-01 15:04:19.000000', NULL, 1),
(3079489, 431757, 32345, '<td valign="top">Great picture, I really love the lighting. Well done</td>', 'Great picture, I really love the lighting. Well done', '2006-12-01 15:04:27.000000', NULL, 1),
