(3081032, 431659, 42013, '<td valign="top">I''m sure you had some fun with this one!</td>', 'I''m sure you had some fun with this one!', '2006-12-02 03:05:49.000000', NULL, 1),
(3081035, 431892, 42013, '<td valign="top">Did you have to add some soap? ;) Good focus and DOF</td>', 'Did you have to add some soap? ;) Good focus and DOF', '2006-12-02 03:06:17.000000', NULL, 1),
(3081037, 432097, 42013, '<td valign="top">Pretty, especially the way the water droplets cling to the petals.</td>', 'Pretty, especially the way the water droplets cling to the petals.', '2006-12-02 03:06:54.000000', NULL, 1),
(3081038, 431524, 42013, '<td valign="top">Hmmmm, your BG is pretty grey, but i wonder how you lit the bulb.</td>', 'Hmmmm, your BG is pretty grey, but i wonder how you lit the bulb.', '2006-12-02 03:07:27.000000', NULL, 1),
(3081039, 431995, 42013, '<td valign="top">This looks like it could be from Yanko''s barnyard series. I like!</td>', 'This looks like it could be from Yanko''s barnyard series. I like!', '2006-12-02 03:09:12.000000', NULL, 1),
