(3083420, 431402, 5792, '<td valign="top">Words defy description. Brilliantly done. Should be a ribbon contender.</td>', 'Words defy description. Brilliantly done. Should be a ribbon contender.', '2006-12-03 11:58:53.000000', NULL, 1),
(3083435, 429805, 5792, '<td valign="top">Everything is good about this image both photographically and for this particular challenge. Its strong tonality is its greatest strength. This should be a top finisher.</td>', 'Everything is good about this image both photographically and for this particular challenge. Its strong tonality is its greatest strength. This should be a top finisher.', '2006-12-03 12:01:47.000000', NULL, 1),
(3083445, 432106, 5792, '<td valign="top">Even without the metaphor of what I presume is a White Russian, the creativity, technical quality and strong perspective on the drink makes this a fantastic composition. Should be a top contender. Its only fault is some slight yellowing around your model.</td>', 'Even without the metaphor of what I presume is a White Russian, the creativity, technical quality and strong perspective on the drink makes this a fantastic composition. Should be a top contender. Its only fault is some slight yellowing around your model.', '2006-12-03 12:05:18.000000', NULL, 1),
