(3086757, 432093, 66193, '<td valign="top">I had this picked for a higher place finish (had it as my second highest score).  Very well done.  I love the color of the marbles, and the composition.  Congratulations on the 14th place (you were robbed!)</td>', 'I had this picked for a higher place finish (had it as my second highest score).  Very well done.  I love the color of the marbles, and the composition.  Congratulations on the 14th place (you were robbed!)', '2006-12-04 14:47:07.000000', NULL, 0),
(3086763, 431906, 66193, '<td valign="top">I''ll echo my earlier comment made during the voting.  I love this one!  Definitely should have been voted higher!!  Nonethless, congrats on a wonderful photo.</td>', 'I''ll echo my earlier comment made during the voting.  I love this one!  Definitely should have been voted higher!!  Nonethless, congrats on a wonderful photo.', '2006-12-04 14:48:37.000000', NULL, 0),
(3086767, 431852, 67841, '<td valign="top">Maybe I was wrong, but I took this to be a bit of a joke &amp; after all the flowery stuff in this challenge I started thinking of it as a political protest, either way I gave you a 5 for standing out! LOL</td>', 'Maybe I was wrong, but I took this to be a bit of a joke & after all the flowery stuff in this challenge I started thinking of it as a political protest, either way I gave you a 5 for standing out! LOL', '2006-12-04 14:49:35.000000', NULL, 0),
